import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { sendPaymentSuccessEmail } from '@/utils/email';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
const supabase = createClient(supabaseUrl, supabaseKey);

export async function POST(request: Request) {
    try {
        const body = await request.json();
        const { utr, amount, orderId } = body;

        if (!utr || !amount) {
            return NextResponse.json({ success: false, message: 'UTR and Amount are required' }, { status: 400 });
        }

        console.log(`Verifying payment: UTR=${utr}, Amount=${amount}, OrderID=${orderId}`);

        // 1. Check Supabase Webhook Logs
        const { data: foundPayment, error } = await supabase
            .from('webhook_logs')
            .select('*')
            .eq('utr', utr)
            .order('created_at', { ascending: false })
            .limit(1)
            .single();

        if (error && error.code !== 'NONE') { // NONE means no rows found
            console.error('Supabase error during verification:', error);
        }

        if (foundPayment) {
            // Check amount (allow small difference)
            if (parseFloat(foundPayment.amount) === parseFloat(amount)) {
                console.log('MATCH FOUND via Webhook (Database)!');

                // Fetch transaction details to get email
                const { data: transaction } = await supabase
                    .from('transactions')
                    .select('*')
                    .eq('utr', utr)
                    .single();

                if (transaction && transaction.customer_details?.email) {
                    await sendPaymentSuccessEmail({
                        to: transaction.customer_details.email,
                        name: transaction.customer_details.name || 'Customer',
                        amount: amount,
                        orderId: transaction.order_id || transaction.session_id || 'N/A',
                        utr: utr,
                        date: new Date().toLocaleString()
                    });
                }

                return NextResponse.json({
                    success: true,
                    message: 'Payment verified successfully',
                    data: { utr, amount, status: 'verified', method: 'webhook' }
                });
            } else {
                console.log(`UTR matched but amount mismatch. Found ${foundPayment.amount}, expected ${amount}`);
            }
        }

        // 2. Mock for testing
        if (utr.startsWith('TEST')) {
            // Try to find the transaction to get email even for mock
            const { data: transaction } = await supabase
                .from('transactions')
                .select('*')
                .eq('utr', utr)
                .single();

            if (transaction && transaction.customer_details?.email) {
                await sendPaymentSuccessEmail({
                    to: transaction.customer_details.email,
                    name: transaction.customer_details.name || 'Customer',
                    amount: amount,
                    orderId: transaction.order_id || transaction.session_id || 'TEST-ORDER',
                    utr: utr,
                    date: new Date().toLocaleString()
                });
            }

            return NextResponse.json({ success: true, message: 'Payment verified (MOCKED)', data: { utr, amount, status: 'verified' } });
        }

        return NextResponse.json({ success: false, message: 'Payment not found yet. Order Cancelled.' });
    } catch (error) {
        console.error('API Error:', error);
        return NextResponse.json({ success: false, message: 'Internal Server Error' }, { status: 500 });
    }
}
