import nodemailer from 'nodemailer';

const transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT) || 587,
    secure: false, // true for 465, false for other ports
    auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS,
    },
});

interface PaymentEmailProps {
    to: string;
    name: string;
    amount: string;
    orderId: string;
    utr: string;
    date: string;
}

export const sendPaymentSuccessEmail = async ({ to, name, amount, orderId, utr, date }: PaymentEmailProps) => {
    if (!to) {
        console.error('Email sending failed: No recipient email provided');
        return;
    }

    try {
        const info = await transporter.sendMail({
            from: process.env.SMTP_FROM || '"Shark Funded" <no-reply@sharkfunded.com>',
            to: to,
            subject: `Payment Successful - Order #${orderId}`,
            html: `
                <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #e0e0e0; border-radius: 10px;">
                    <div style="text-align: center; margin-bottom: 20px;">
                        <h2 style="color: #635BFF;">Payment Confirmed</h2>
                        <p style="color: #666;">Thank you for your payment, ${name}!</p>
                    </div>
                    
                    <div style="background-color: #f9fafb; padding: 20px; border-radius: 8px; margin-bottom: 20px;">
                        <p style="margin: 5px 0; font-size: 14px; color: #666;">Amount Paid</p>
                        <p style="margin: 0 0 15px 0; font-size: 24px; font-weight: bold; color: #111;">₹${amount}</p>
                        
                        <div style="border-top: 1px solid #e5e7eb; margin: 10px 0;"></div>
                        
                        <p style="margin: 5px 0; font-size: 12px; color: #888;">Order ID</p>
                        <p style="margin: 0 0 10px 0; font-size: 14px; font-weight: bold; color: #333;">${orderId}</p>
                        
                        <p style="margin: 5px 0; font-size: 12px; color: #888;">Transaction Reference (UTR)</p>
                        <p style="margin: 0 0 10px 0; font-size: 14px; font-weight: bold; color: #333;">${utr}</p>
                        
                        <p style="margin: 5px 0; font-size: 12px; color: #888;">Date</p>
                        <p style="margin: 0 0 0 0; font-size: 14px; font-weight: bold; color: #333;">${date}</p>
                    </div>
                    
                    <div style="text-align: center; color: #888; font-size: 12px; margin-top: 20px;">
                        <p>If you have any questions, please contact support.</p>
                        <p>&copy; ${new Date().getFullYear()} Shark Funded. All rights reserved.</p>
                    </div>
                </div>
            `,
        });

        console.log('Payment success email sent:', info.messageId);
        return info;
    } catch (error) {
        console.error('Error sending payment success email:', error);
        // Don't throw, just log. We don't want to fail the payment response if email fails.
    }
};
